///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('cal_startDate').getValue()> $c.util.getComponent('cal_endDate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('dma_SearchReq').set('method', 'searchLinkDisclsApplList');
    frm.action = 'linkDisclsAppl.do';
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name regist
 * @description regist 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.regist = async function () {
    const frm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'linkDisclsApplRegisterForm');
    frm.action = 'linkDisclsAppl.do';
    const nr = await scwin.tx_fn_Regist();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil21101/jldfil21101.xml", { "method": 'linkDisclsApplRegisterForm' });
    }
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function () {
    const frm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'linkDisclsApplModifyForm');
    frm.action = 'linkDisclsAppl.do';
    const nr = await scwin.tx_fn_Modify();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil21102/jldfil21102.xml", { "method": 'linkDisclsApplModifyForm' });
    }
};

/**
 * @method
 * @name deleteSearchReq
 * @description delete Search Req 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteSearchReq = async function () {
    const frm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'linkDisclsApplRemoveForm');
    frm.action = 'linkDisclsAppl.do';
    const nr = await scwin.tx_fn_Delete();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil21103/jldfil21103.xml", { "method": 'linkDisclsApplRemoveForm' });
    }
};

/**
 * @method
 * @name goCompanyList
 * @description go Company List 처리
 * @returns {void}
 * @hidden N
 */
scwin.goCompanyList = function () {
    const linkDisclsAppURL = '/company/linkDisclsAppl.do?method=searchLinkDisclsCompanyList';
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(linkDisclsAppURL));
};
